// Host-JVM harness for the CKey JNI bridge. Plain Java, no Android, no Kotlin
// runtime needed: it calls org.openckey.ckey.CKeyNative's static native
// methods directly, so it runs against either the Kotlin-compiled class or
// the Java mirror generated by gen_mirror.py. See run.sh.

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

import org.openckey.ckey.CKeyException;
import org.openckey.ckey.CKeyNative;

public final class HostHarness {
    static int checks = 0;

    static void check(boolean ok, String what) {
        checks++;
        if (!ok) throw new AssertionError("FAILED: " + what);
        System.out.println("ok   " + what);
    }

    interface Body { void run() throws Exception; }

    static void throwsType(Class<? extends Throwable> type, Body body, String what) throws Exception {
        try {
            body.run();
        } catch (Throwable t) {
            check(type.isInstance(t), what + " -> " + t);
            return;
        }
        check(false, what + " (no exception)");
    }

    static int[] info5() { return new int[5]; }

    /** Straight RGBA8 -> Rec. 709 luma, composited over white, placed in a larger frame. */
    static byte[] frameFromRgba(byte[] rgba, int side, int frameW, int frameH, int stride, int x0, int y0) {
        byte[] frame = new byte[stride * frameH];
        Arrays.fill(frame, (byte) 0xff);
        for (int y = 0; y < side; y++)
            for (int x = 0; x < side; x++) {
                int p = (y * side + x) * 4;
                int r = rgba[p] & 0xff, g = rgba[p + 1] & 0xff, b = rgba[p + 2] & 0xff, a = rgba[p + 3] & 0xff;
                int luma = (2126 * r + 7152 * g + 722 * b + 5000) / 10000;
                frame[(y0 + y) * stride + x0 + x] = (byte) ((luma * a + 255 * (255 - a) + 127) / 255);
            }
        return frame;
    }

    public static void main(String[] args) throws Exception {
        int features = CKeyNative.nativeFeatures();
        System.out.println("features=" + features + " version=" + CKeyNative.nativeSoftwareVersion() + " abi=" + CKeyNative.nativeAbiVersion());
        check((features & 7) == 7, "scan, render and telemetry compiled in");
        check(CKeyNative.nativeSoftwareVersion().matches("^0\\.[0-9]+\\.[0-9]+(-(build|dev)\\.[0-9]{1,6})?$"), "software version matches the telemetry schema");
        check(CKeyNative.nativeCapacity(1, 1, 0) > 0 && CKeyNative.nativeCapacity(99, 1, 0) == 0, "capacity");
        check(CKeyNative.nativeModulesAcross(1) == 29 && CKeyNative.nativeModulesAcross(31) == 232, "modules across v1/v31");

        // ---- encode -> render RGBA -> gray -> decode (Profile 0 standard)
        String text = "https://openckey.org/hello?from=android-jni";
        byte[] payload = text.getBytes(StandardCharsets.UTF_8);
        byte[] symbol = CKeyNative.nativeEncode(payload, 0, 1, 0);
        int[] info = CKeyNative.nativeSymbolInfo(symbol);
        check(info[0] >= 1 && info[1] == 1 && info[2] == 0 && info[3] == payload.length, "symbol info " + Arrays.toString(info));

        int side = 480;
        byte[] rgba = CKeyNative.nativeRenderRaster(symbol, null, null, null, side, 0, false, false, false, 4, 1.0, true, null, 0, 0);
        check(rgba.length == side * side * 4, "RGBA buffer size");
        int frameW = 760, frameH = 620, stride = 800, x0 = 140, y0 = 70;
        byte[] frame = frameFromRgba(rgba, side, frameW, frameH, stride, x0, y0);
        int[] dinfo = info5();
        double[] quad = new double[8];
        byte[] decoded = CKeyNative.nativeDecodeArray(frame, 0, frameW, frameH, stride, 6, dinfo, quad);
        check(decoded != null && Arrays.equals(decoded, payload), "round trip via byte[] (P0 v" + dinfo[1] + ", candidates " + dinfo[3] + ")");
        check(dinfo[0] == 0 && dinfo[1] == info[0] && dinfo[2] == 0, "decode reports profile P0 and the encoded version");
        check(quad[0] > x0 - 20 && quad[0] < x0 + side + 20, "quad is in frame coordinates");

        // Same frame through a direct ByteBuffer with a non-zero offset.
        int pad = 37;
        ByteBuffer direct = ByteBuffer.allocateDirect(pad + frame.length);
        direct.position(pad);
        direct.put(frame);
        direct.position(0);
        byte[] viaBuffer = CKeyNative.nativeDecodeBuffer(direct, pad, frameW, frameH, stride, 6, info5(), new double[8]);
        check(viaBuffer != null && Arrays.equals(viaBuffer, payload), "round trip via direct ByteBuffer + offset");

        // UTF-8 beyond the BMP, PRINT layout, level H, GRAY8 output, inverted polarity.
        byte[] utf8 = "Grüße aus Köln 👋 — address:1 Main St".getBytes(StandardCharsets.UTF_8);
        byte[] printSymbol = CKeyNative.nativeEncode(utf8, 0, 3, 1);
        byte[] gray = CKeyNative.nativeRenderRaster(printSymbol, null, null, null, 400, 1, true, false, false, 4, 1.0, true, null, 0, 0);
        check(gray.length == 400 * 400, "GRAY8 buffer size");
        byte[] inverted = new byte[gray.length];
        for (int i = 0; i < gray.length; i++) inverted[i] = (byte) (255 - (gray[i] & 0xff));
        int[] pinfo = info5();
        byte[] printDecoded = CKeyNative.nativeDecodeArray(gray, 0, 400, 400, 400, 6, pinfo, new double[8]);
        check(printDecoded != null && Arrays.equals(printDecoded, utf8) && pinfo[0] == 1 && pinfo[2] == 1, "PRINT layout (P0.1) round trip, level H");
        byte[] invDecoded = CKeyNative.nativeDecodeArray(inverted, 0, 400, 400, 400, 6, info5(), new double[8]);
        check(invDecoded != null && Arrays.equals(invDecoded, utf8), "inverted polarity round trip");

        // Blank frame: no result, no exception.
        byte[] blank = new byte[320 * 240];
        Arrays.fill(blank, (byte) 0x80);
        check(CKeyNative.nativeDecodeArray(blank, 0, 320, 240, 320, 6, info5(), new double[8]) == null, "blank frame decodes to null");

        // ---- transparent output and premultiplication
        byte[] straight = CKeyNative.nativeRenderRaster(symbol, null, null, null, 128, 0, false, true, false, 4, 1.0, true, null, 0, 0);
        byte[] premul = CKeyNative.nativeRenderRaster(symbol, null, null, null, 128, 0, false, true, true, 4, 1.0, true, null, 0, 0);
        int zeroAlpha = 0, partial = 0, mismatches = 0;
        for (int p = 0; p < straight.length; p += 4) {
            int a = straight[p + 3] & 0xff;
            if (a == 0) zeroAlpha++;
            if (a > 0 && a < 255) partial++;
            if ((premul[p + 3] & 0xff) != a) mismatches++;
            for (int c = 0; c < 3; c++) {
                int expect = ((straight[p + c] & 0xff) * a + 127) / 255;
                if ((premul[p + c] & 0xff) != expect) mismatches++;
                if ((premul[p + c] & 0xff) > (premul[p + 3] & 0xff)) mismatches++;  // premultiplied invariant: c <= a
            }
        }
        check(zeroAlpha > 0, "transparent output has alpha-0 pixels (" + zeroAlpha + ")");
        check(partial > 0, "coverage antialiasing yields partial alpha (" + partial + ")");
        check(mismatches == 0, "premultiplied RGBA = round(c * a / 255) with c <= a");

        // ---- exports
        byte[] png = CKeyNative.nativeRenderPng(symbol, null, null, null, 256, 0, true, 4, 1.0, true, null, 0, 0, 300.0);
        check(png.length > 8 && (png[0] & 0xff) == 0x89 && png[1] == 'P' && png[2] == 'N' && png[3] == 'G', "PNG signature (" + png.length + " bytes)");
        String svg = CKeyNative.nativeRenderSvg(symbol, null, null, null, 8);
        check(svg.contains("<svg") && svg.trim().endsWith("</svg>"), "SVG export (" + svg.length() + " chars)");
        byte[] pdf = CKeyNative.nativeRenderPdf(symbol, null, null, null, 144.0, false);
        check(new String(pdf, 0, 5, StandardCharsets.US_ASCII).equals("%PDF-"), "PDF export (" + pdf.length + " bytes)");

        // ---- styles
        int[] ints = new int[15];
        double[] doubles = new double[4];
        CKeyNative.nativeStylePreset(1, ints, doubles);
        check(ints[2] == 0xf6eee0 && ints[8] == 2 && doubles[0] == 0.6 && ints[14] == 0, "CONCEPT preset marshalled (ink, accents, bevel, policy strict)");
        String report = CKeyNative.nativeCheckStyle(symbol, ints, doubles, null);
        check(report.startsWith("style OK"), "check style: " + report);
        byte[] concept = CKeyNative.nativeRenderRaster(symbol, ints, doubles, null, side, 0, false, false, false, 4, 1.0, true, null, 0, 0);
        byte[] conceptFrame = frameFromRgba(concept, side, frameW, frameH, stride, x0, y0);
        byte[] conceptDecoded = CKeyNative.nativeDecodeArray(conceptFrame, 0, frameW, frameH, stride, 6, info5(), new double[8]);
        check(conceptDecoded != null && Arrays.equals(conceptDecoded, payload), "CONCEPT style (light on dark) round trip");

        int[] lowContrast = new int[15];
        double[] d0 = new double[4];
        CKeyNative.nativeStylePreset(0, lowContrast, d0);
        lowContrast[2] = 0xf0f0f0; lowContrast[3] = 0xf0f0f0;  // near-white ink on white
        throwsType(CKeyException.class, () -> CKeyNative.nativeCheckStyle(symbol, lowContrast, d0, null), "low-contrast style refused with the core's diagnostic");
        try {
            CKeyNative.nativeRenderRaster(symbol, lowContrast, d0, null, 128, 0, false, false, false, 4, 1.0, true, null, 0, 0);
        } catch (CKeyException e) {
            check(e.getStatus() == 1 && !e.getMessage().isEmpty(), "strict render refusal explains: " + e.getMessage());
        }
        lowContrast[14] = 1;  // ADAPTIVE: the renderer repairs the style
        byte[] adaptive = CKeyNative.nativeRenderRaster(symbol, lowContrast, d0, null, side, 0, false, false, false, 4, 1.0, true, null, 0, 0);
        byte[] adaptiveDecoded = CKeyNative.nativeDecodeArray(frameFromRgba(adaptive, side, frameW, frameH, stride, x0, y0), 0, frameW, frameH, stride, 6, info5(), new double[8]);
        check(adaptiveDecoded != null && Arrays.equals(adaptiveDecoded, payload), "ADAPTIVE policy repairs the style and the result decodes");

        // Logo pixels path (straight RGBA).
        byte[] logo = new byte[8 * 8 * 4];
        for (int i = 0; i < logo.length; i += 4) { logo[i] = (byte) 200; logo[i + 3] = (byte) 255; }
        int[] logoInts = new int[15];
        double[] logoDoubles = new double[4];
        CKeyNative.nativeStylePreset(0, logoInts, logoDoubles);
        logoInts[13] = 1;
        byte[] withLogo = CKeyNative.nativeRenderRaster(symbol, logoInts, logoDoubles, null, 256, 0, false, false, false, 4, 1.0, true, logo, 8, 8);
        check(withLogo.length == 256 * 256 * 4, "raster with a logo bitmap");

        // ---- certification (optional core module)
        if ((features & 8) != 0) {
            int[] outI = new int[15];
            double[] outD = new double[4];
            double[] cert = new double[9];
            String msg = CKeyNative.nativeCertify(symbol, null, null, null, false, null, null, 0, 0, null, outI, outD, cert);
            check(cert[0] == 0 && cert[1] == 1, "default style certified: " + msg);
            String tmsg = CKeyNative.nativeCertify(symbol, null, null, null, true, null, null, 0, 0, null, outI, outD, cert);
            check(cert[1] == 0, "transparent without a backdrop is never certified: " + tmsg);
            String bmsg = CKeyNative.nativeCertify(symbol, null, null, null, true, new int[] {0xffffff, 0xeeeeee}, null, 0, 0,
                    new double[] {8, 0.9, 0.03, 0.2, 2}, outI, outD, cert);
            check(cert[1] == 1, "transparent over light backdrops certified: " + bmsg);
        } else {
            System.out.println("skip certification (ckey_certify.cpp not in this core)");
        }

        // ---- argument validation (Java exceptions, never crashes)
        throwsType(IllegalArgumentException.class, () -> CKeyNative.nativeSymbolInfo(new byte[10]), "wrong-size symbol blob");
        byte[] corrupt = symbol.clone();
        corrupt[0] ^= 0x55;  // abi_version
        throwsType(IllegalArgumentException.class, () -> CKeyNative.nativeRenderSvg(corrupt, null, null, null, 4), "corrupt symbol header");
        throwsType(IllegalArgumentException.class, () -> CKeyNative.nativeDecodeArray(frame, 0, frameW, frameH, frameW - 1, 6, info5(), new double[8]), "stride < width");
        throwsType(IllegalArgumentException.class, () -> CKeyNative.nativeDecodeArray(frame, 100, frameW, frameH, stride, 6, info5(), new double[8]), "offset past the end");
        throwsType(IllegalArgumentException.class, () -> CKeyNative.nativeDecodeBuffer(ByteBuffer.allocate(100), 0, 10, 10, 10, 6, info5(), new double[8]), "heap buffer refused by native");
        throwsType(IllegalArgumentException.class, () -> CKeyNative.nativeRenderRaster(symbol, new int[3], new double[4], null, 64, 0, false, false, false, 4, 1, true, null, 0, 0), "style array shape");
        throwsType(NullPointerException.class, () -> CKeyNative.nativeEncode(null, 0, 1, 0), "null payload");
        throwsType(CKeyException.class, () -> CKeyNative.nativeEncode(new byte[20000], 0, 1, 0), "oversized payload");
        throwsType(CKeyException.class, () -> CKeyNative.nativeEncode(new byte[100], 1, 3, 0), "payload over a fixed version's capacity");

        // ---- telemetry
        CKeyNative.nativeTelemetryResetForTesting();
        check(CKeyNative.nativeTelemetryGetMode() == 1, "telemetry default mode 1");
        check(CKeyNative.nativeTelemetrySetMode(3) == 1 && CKeyNative.nativeTelemetryGetMode() == 1, "mode 3 refused, mode unchanged");
        check(CKeyNative.nativeTelemetrySetClient("android", CKeyNative.nativeSoftwareVersion(), "android") == 0, "set_client android");
        check(CKeyNative.nativeTelemetrySetClient("kotlin", "1", "android") == 1, "invalid client refused");
        String endpoint = CKeyNative.nativeTelemetryEndpoint();
        check(endpoint.equals("https://openckey.org/api/telemetry/v1/batch"), "endpoint " + endpoint);
        long t = 1000;
        CKeyNative.nativeTelemetrySessionBegin(t);
        CKeyNative.nativeTelemetryFrame(t + 10, 7);
        CKeyNative.nativeTelemetryFrame(t + 50, 30);
        check(CKeyNative.nativeTelemetrySessionSuccess(t + 60, 0) == 0, "session success P0");
        check(CKeyNative.nativeTelemetrySessionSuccess(t + 70, 9) == 1, "invalid profile code refused");
        CKeyNative.nativeTelemetrySessionEnd(t + 80);
        long[] snap = new long[33];
        check(CKeyNative.nativeTelemetrySnapshot(snap) == 0 && snap[0] == 1 && snap[1] == 1 && snap[3] == 2 && snap[4] == 1, "snapshot " + Arrays.toString(Arrays.copyOf(snap, 9)));
        check(snap[9] == 1 && snap[10] == 60 && snap[11 + 2] == 1, "time-to-decode histogram (60 ms in bucket 2)");
        check(!CKeyNative.nativeTelemetryShouldSend(t + 100), "no batch before the delta is 60 s old");
        check(CKeyNative.nativeTelemetryShouldSend(t + 61_000), "batch due after 60 s");
        long[] id = new long[1];
        String batch = CKeyNative.nativeTelemetryTakeBatch("2026-11-05", id);
        check(batch != null && id[0] != 0 && batch.contains("\"sdk\":\"android\"") && batch.contains("\"platform\":\"android\"") && batch.contains("\"day\":\"2026-11-05\""), "batch JSON: " + batch);
        check(CKeyNative.nativeTelemetryTakeBatch("2026-11-05", new long[1]) == null, "no second batch while one is in flight");
        throwsType(CKeyException.class, () -> CKeyNative.nativeTelemetryTakeBatch("2026-13-45", new long[1]), "invalid day refused");
        check(CKeyNative.nativeTelemetryBatchResult(id[0], 204, t + 62_000) == 0, "batch result 204");
        check(CKeyNative.nativeTelemetryBatchResult(id[0], 204, t + 62_000) == 1, "stale batch id refused");
        String state = CKeyNative.nativeTelemetryExportState();
        check(state.startsWith("{\"state\":1"), "export state");
        check(CKeyNative.nativeTelemetrySetMode(0) == 0 && CKeyNative.nativeTelemetrySnapshot(snap) == 0 && snap[0] == 0, "mode 0 purges counters");
        check(CKeyNative.nativeTelemetryImportState(state) == 1, "import refused in mode 0");
        CKeyNative.nativeTelemetrySetMode(2);
        check(CKeyNative.nativeTelemetryImportState(state) == 0, "import accepted in mode 2");
        CKeyNative.nativeTelemetrySessionBegin(t);
        check(!CKeyNative.nativeTelemetryShouldSend(t + 10_000_000), "mode 2 never sends");
        CKeyNative.nativeTelemetryResetForTesting();

        System.out.println("HostHarness: " + checks + " checks passed");
    }
}
